<div style="background: #ffffff; border: 2px solid #991b1b; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 14px rgba(0,0,0,0.06);"><!-- Barra de navegación por preguntas (1 a 10) -->
<div style="background: #f8fafc; border-bottom: 2px solid #991b1b; padding: 10px 12px; display: flex; justify-content: center; align-items: center; gap: 6px; flex-wrap: wrap;"><span style="font-size: 0.82rem; font-weight: 800; color: #64748b; margin-right: 4px; text-transform: uppercase;">Preguntas:</span>
