<!-- Barra inferior: Marcador, navegación y botón finalizar -->
<div style="background: #fdfaf2; border-top: 1px solid #fed7aa; padding: 14px 20px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 10px;">
<div style="display: flex; gap: 14px; font-weight: 800; font-size: 0.95rem;"><span style="color: #15803d;">Bien = <span id="marcador-bien">0</span></span> <span style="color: #b91c1c;">Mal = <span id="marcador-mal">0</span></span> <span style="color: #0284c7;">Nota = <span id="marcador-nota">0</span></span></div>
