<!-- Cuadro de estadísticas -->
<div style="display: flex; justify-content: space-around; background: #fffbeb; border: 1px solid #fed7aa; border-radius: 8px; padding: 14px; margin-bottom: 20px;">
<div style="text-align: center;">
<div style="font-size: 0.85rem; font-weight: bold; color: #64748b; text-transform: uppercase;">Aciertos</div>
<div id="resumen-aciertos" style="font-size: 1.6rem; font-weight: 900; color: #15803d;">0</div>
</div>
<div style="text-align: center;">
<div style="font-size: 0.85rem; font-weight: bold; color: #64748b; text-transform: uppercase;">Fallos</div>
