</div>
</div>
<!-- Desglose por preguntas -->
<div id="lista-desglose-resumen" style="display: flex; flex-direction: column; gap: 8px; max-height: 280px; overflow-y: auto; padding-right: 4px; margin-bottom: 20px;"><!-- Filas de detalle generadas por JS --></div>
<!-- Botonera de la pantalla resumen -->
<div style="display: flex; justify-content: center; gap: 12px; flex-wrap: wrap;">
<div onclick="irAPregunta(0)" style="background: #e2e8f0; color: #334155; font-weight: 800; font-size: 0.9rem; padding: 9px 20px; border-radius: 6px; cursor: pointer; text-transform: uppercase;">Revisar preguntas</div>
<div onclick="reiniciarTest()" style="background: #f57c00; color: #ffffff; font-weight: 800; font-size: 0.9rem; padding: 9px 24px; border-radius: 6px; cursor: pointer; text-transform: uppercase; box-shadow: 0 2px 5px rgba(245, 124, 0, 0.35);">Repetir test</div>
</div>
</div>
</div>
</div>
