    }

    .opcion-card.correcta-marcada {
      background: #dcfce7 !important;
      border-color: #16a34a !important;
    }
    .opcion-card.correcta-marcada .opcion-letra {
      border-color: #16a34a;
      color: #16a34a;
    }
    .opcion-card.incorrecta-marcada {
      background: #fee2e2 !important;
      border-color: #dc2626 !important;
    }
    .opcion-card.incorrecta-marcada .opcion-letra {
