    }

    .f-frac {
      display: inline-flex;
      flex-direction: column;
      align-items: center;
      vertical-align: middle;
      line-height: 1;
      padding: 0 4px;
    }
    .f-frac .fn, .f-frac .fd {
      font-size: 1.25rem;
      font-weight: 800;
      color: #1e3a8a;
    }
    .f-frac .fl {
      width: 100%;
      height: 2px;
      background: #1e3a8a;
      margin: 3px 0;
    }
  </style>
<div id="test-algebra-app" style="margin: 15px auto; max-width: 620px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"></div>
<script>
(function() {
  function htmlFrac(n, d) {
    return `<span class="f-frac"><span class="fn">${n}</span><span class="fl"></span><span class="fd">${d}</span></span>`;
  }

  // Generador de raíz cuadrada en SVG continuo para lenguaje algebraico
  function svgRadical(contenidoHTML, anchoTotal, textoX) {
    let w = anchoTotal || 70;
    let endX = w - 2;
    let tX = textoX || 16;
    return `
      <span style="display:inline-flex; align-items:center; vertical-align:middle; line-height:1;">
        <svg width="${w}" height="36" viewBox="0 0 ${w} 36" style="overflow:visible;">
          <path d="M 2 20 L 5 29 L 12 5 L ${endX} 5" 
                fill="none" 
                stroke="#1e3a8a" 
                stroke-width="2.5" 
                stroke-linecap="round" 
                stroke-linejoin="round" />
          <foreignObject x="${tX}" y="7" width="${w - tX}" height="28">
            <div xmlns="http://www.w3.org/1999/xhtml" style="font-family:-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; font-size:1.15rem; font-weight:800; color:#1e3a8a; line-height:1; white-space:nowrap;">
              ${contenidoHTML}
            </div>
          </foreignObject>
        </svg>
      </span>
    `;
  }

  const PREGUNTAS = [
    // 1
    {
      enunciado: "Escoge la expresión algebraica del cuádruple de un número, más 9",
      opciones: [
        { html: "4 x + 9", correcta: true },
        { html: htmlFrac("x", "4") + " + 9", correcta: false },
        { html: "9 x + 4", correcta: false },
        { html: "4 (x + 9)", correcta: false }
      ],
      retro: "El <strong>cuádruple de un número</strong> es multiplicarlo por 4 (4x). Al sumar 9 resulta <strong>4x + 9</strong>."
    },
    // 2
    {
      enunciado: "Escoge la expresión algebraica de un tercio de un número, más 10",
      opciones: [
        { html: htmlFrac("x", "3") + " + 10", correcta: true },
        { html: htmlFrac("x + 10", "3"), correcta: false },
        { html: "10 x + 3", correcta: false },
        { html: "3 x + 10", correcta: false }
      ],
      retro: "<strong>Un tercio de un número</strong> es dividirlo entre 3 (x/3). La suma de 10 se añade aparte: <strong>" + htmlFrac("x", "3") + " + 10</strong>."
    },
    // 3
    {
      enunciado: "Escoge la expresión algebraica de la mitad de la suma de un número (cualquiera) más 12",
      opciones: [
        { html: htmlFrac("12", "2") + " + x", correcta: false },
        { html: htmlFrac("24 + 12", "2"), correcta: false },
        { html: htmlFrac("x", "2") + " + 12", correcta: false },
        { html: htmlFrac("x + 12", "2"), correcta: true }
      ],
      retro: "Primero se calcula <em>la suma del número más 12</em> (x + 12) y luego se calcula <strong>su mitad</strong> (dividiendo todo el bloque entre 2): <strong>" + htmlFrac("x + 12", "2") + "</strong>."
    },
    // 4
    {
      enunciado: "La semisuma de dos números",
      opciones: [
        { html: htmlFrac("x + y", "2"), correcta: true },
        { html: htmlFrac("x", "2") + " + y", correcta: false },
        { html: htmlFrac("x − y", "2"), correcta: false },
        { html: htmlFrac("x · y", "2"), correcta: false }
      ],
      retro: "El prefijo <em>semi-</em> significa mitad. La <strong>semisuma</strong> es la suma de los dos números dividida entre 2: <strong>" + htmlFrac("x + y", "2") + "</strong>."
    },
    // 5
    {
      enunciado: "Escoge la expresión algebraica de la mitad del producto de dos números",
      opciones: [
        { html: htmlFrac("x · 6", "2"), correcta: false },
        { html: htmlFrac("x", "2") + " · y", correcta: false },
        { html: htmlFrac("x − y", "2"), correcta: false },
        { html: htmlFrac("x · y", "2"), correcta: true }
      ],
      retro: "El producto de dos números es x · y. Su mitad es dividir ese producto entre dos: <strong>" + htmlFrac("x · y", "2") + "</strong>."
    },
    // 6 - CON RAÍCES VECTORIALES SVG IMPECABLES
    {
      enunciado: "Escoge la expresión algebraica de la raíz cuadrada de la suma de dos cuadrados",
      opciones: [
        { html: "x² + y²", correcta: false },
        { html: svgRadical("x² + y²", 88, 16), correcta: true },
        { html: "x + y", correcta: false },
        { html: svgRadical("x²", 48, 15) + " + " + svgRadical("y²", 48, 15), correcta: false }
      ],
      retro: "Primero se calcula la suma de los dos cuadrados (x² + y²) y a continuación la raíz cuadrada que abarca toda la suma: <strong>√(x² + y²)</strong>."
    },
    // 7
    {
      enunciado: "Escoge la expresión algebraica que da el 50 % de un número",
      opciones: [
        { html: htmlFrac("50", "10") + " x", correcta: false },
        { html: htmlFrac("50", "100 x"), correcta: false },
        { html: htmlFrac("100 x", "50"), correcta: false },
        { html: "0.5 x", correcta: true }
      ],
      retro: "El 50 % de x es (50/100) · x = 0,5 x. La opción correcta es <strong>0.5 x</strong>."
    },
    // 8
    {
      enunciado: "Escoge la expresión algebraica del cuadrado de la suma de dos números",
      opciones: [
        { html: "x + y²", correcta: false },
        { html: "x² + y²", correcta: false },
        { html: "(z + y)²", correcta: true },
        { html: "(10 + y)²", correcta: false }
      ],
      retro: "El <strong>cuadrado de la suma</strong> eleva a potencia dos todo el paréntesis de la suma: <strong>(z + y)²</strong> (o (x + y)²)."
    },
    // 9
    {
      enunciado: "Escoge la expresión algebraica del cuadrado de la semisuma de dos números.",
      opciones: [
        { html: htmlFrac("x + y²", "2"), correcta: false },
        { html: htmlFrac("(x + y)²", "2"), correcta: false },
        { html: htmlFrac("(x + y)²", "4"), correcta: true },
        { html: htmlFrac("x² + y²", "4"), correcta: false }
      ],
      retro: "La semisuma es (x + y)/2. Al elevar toda la fracción al cuadrado: <strong>((x + y)/2)² = " + htmlFrac("(x + y)²", "4") + "</strong>, pues 2² = 4 en el denominador."
    },
    // 10
    {
      enunciado: "Escoge la expresión algebraica de la media aritmética de tres números.",
      opciones: [
        { html: htmlFrac("x + y + z", "2"), correcta: false },
        { html: "( " + htmlFrac("x + y", "2") + " + z ) /2", correcta: false },
        { html: htmlFrac("x + y + z", "3"), correcta: true },
        { html: "0.5x + 0.5y + 0.5z", correcta: false }
      ],
      retro: "La <strong>media aritmética</strong> de 3 valores se calcula sumando los tres y dividiendo el total entre 3: <strong>" + htmlFrac("x + y + z", "3") + "</strong>."
    }
  ];

  let indiceActual = 0;
  let respuestasUsuario = Array(10).fill(null); // null, 'acierto', 'fallo'

  function renderNavegacion() {
    const nav = document.getElementById('nav-preguntas');
    nav.innerHTML = '';
    for (let i = 0; i < PREGUNTAS.length; i++) {
      let btn = document.createElement('div');
      btn.className = 'btn-nav-num';
      btn.textContent = (i + 1);

      if (i === indiceActual) btn.classList.add('activa');
      if (respuestasUsuario[i] === 'acierto') btn.classList.add('acertada');
      if (respuestasUsuario[i] === 'fallo') btn.classList.add('fallada');

      btn.onclick = function() { irAPregunta(i); };
      nav.appendChild(btn);
    }
  }

  function actualizarMarcador() {
    let bien = respuestasUsuario.filter(r => r === 'acierto').length;
    let mal = respuestasUsuario.filter(r => r === 'fallo').length;
    document.getElementById('marcador-bien').textContent = bien;
    document.getElementById('marcador-mal').textContent = mal;
    document.getElementById('marcador-nota').textContent = bien;
  }

  window.irAPregunta = function(idx) {
    indiceActual = idx;
    document.getElementById('pantalla-inicio-test').style.display = 'none';
    document.getElementById('pantalla-resumen-test').style.display = 'none';
    document.getElementById('pantalla-pregunta-test').style.display = 'block';

    const p = PREGUNTAS[idx];
    document.getElementById('txt-num-pregunta').textContent = `Pregunta ${idx + 1} de 10`;
    document.getElementById('txt-enunciado-pregunta').textContent = p.enunciado;

    const cont = document.getElementById('contenedor-opciones');
    cont.innerHTML = '';

    const letras = ['A', 'B', 'C', 'D'];
    const yaRespondida = (respuestasUsuario[idx] !== null);

    p.opciones.forEach((opc, oIdx) => {
      let card = document.createElement('div');
      card.className = 'opcion-card';

      if (yaRespondida && opc.correcta) card.classList.add('correcta-marcada');

      card.innerHTML = `
        <div class="opcion-letra">${letras[oIdx]}</div>
        <div class="opcion-texto">${opc.html}</div>
      `;

      card.onclick = function() {
        if (respuestasUsuario[idx] === null) {
          evaluarRespuesta(oIdx);
        }
      };

      cont.appendChild(card);
    });

    const panelRetro = document.getElementById('panel-retroalimentacion-test');
    if (yaRespondida) {
      panelRetro.innerHTML = p.retro;
      panelRetro.style.display = 'block';
    } else {
      panelRetro.style.display = 'none';
    }

    renderNavegacion();
    actualizarMarcador();
  };

  function evaluarRespuesta(opcIdx) {
    const p = PREGUNTAS[indiceActual];
    const cards = document.querySelectorAll('#contenedor-opciones .opcion-card');
    const esCorrecta = p.opciones[opcIdx].correcta;

    if (esCorrecta) {
      respuestasUsuario[indiceActual] = 'acierto';
      cards[opcIdx].classList.add('correcta-marcada');
    } else {
      respuestasUsuario[indiceActual] = 'fallo';
      cards[opcIdx].classList.add('incorrecta-marcada');
      p.opciones.forEach((opc, idx) => {
        if (opc.correcta) cards[idx].classList.add('correcta-marcada');
      });
    }

    const panelRetro = document.getElementById('panel-retroalimentacion-test');
    panelRetro.innerHTML = p.retro;
    panelRetro.style.display = 'block';

    renderNavegacion();
    actualizarMarcador();
  }

  window.siguientePregunta = function() {
    if (indiceActual < PREGUNTAS.length - 1) {
      irAPregunta(indiceActual + 1);
    } else {
      mostrarPantallaResumen();
    }
  };

  window.anteriorPregunta = function() {
    if (indiceActual > 0) {
      irAPregunta(indiceActual - 1);
    }
  };

  window.mostrarPantallaResumen = function() {
    document.getElementById('pantalla-inicio-test').style.display = 'none';
    document.getElementById('pantalla-pregunta-test').style.display = 'none';
    document.getElementById('pantalla-resumen-test').style.display = 'block';

    let bien = respuestasUsuario.filter(r => r === 'acierto').length;
    let mal = respuestasUsuario.filter(r => r === 'fallo').length;
    let blanco = respuestasUsuario.filter(r => r === null).length;

    document.getElementById('resumen-aciertos').textContent = bien;
    document.getElementById('resumen-fallos').textContent = mal;
    document.getElementById('resumen-blanco').textContent = blanco;
    document.getElementById('resumen-nota').textContent = bien + ' / 10';

    const lista = document.getElementById('lista-desglose-resumen');
    lista.innerHTML = '';

    PREGUNTAS.forEach((p, idx) => {
      let estado = respuestasUsuario[idx];
      let fila = document.createElement('div');
      fila.style.display = 'flex';
      fila.style.justifyContent = 'space-between';
      fila.style.alignItems = 'center';
      fila.style.padding = '8px 12px';
      fila.style.borderRadius = '6px';
      fila.style.fontSize = '0.9rem';
      fila.style.cursor = 'pointer';

      let etiqueta = '';
      if (estado === 'acierto') {
        fila.style.background = '#f0fdf4';
        fila.style.border = '1px solid #bbf7d0';
        etiqueta = '<span style="color:#15803d; font-weight:800;">✓ Correcta</span>';
      } else if (estado === 'fallo') {
        fila.style.background = '#fef2f2';
        fila.style.border = '1px solid #fecaca';
        etiqueta = '<span style="color:#b91c1c; font-weight:800;">✗ Incorrecta</span>';
      } else {
        fila.style.background = '#f8fafc';
        fila.style.border = '1px solid #e2e8f0';
        etiqueta = '<span style="color:#64748b; font-weight:700;">Sin responder</span>';
      }

      fila.innerHTML = `
        <span style="font-weight:700; color:#1e293b; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:70%;">
          ${idx + 1}. ${p.enunciado}
        </span>
        ${etiqueta}
      `;

      fila.onclick = function() { irAPregunta(idx); };
      lista.appendChild(fila);
    });

    renderNavegacion();
  };

  window.reiniciarTest = function() {
    respuestasUsuario = Array(10).fill(null);
    irAPregunta(0);
  };

  renderNavegacion();
})();
</script>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

{"ideviceId":"idevice-1791800480147-iocx5ig2x","textInfoDurationInput":"","textInfoDurationTextInput":"Duración","textInfoParticipantsInput":"","textInfoParticipantsTextInput":"Agrupamiento","textTextarea":"<!-- TUTOR INTERACTIVO: RESOLUCIÓN GUIADA DE ECUACIONES RACIONALES -->
<div id="tutor-racionales-app" style="margin: 10px auto; width: 100%; max-width: 820px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1e293b; user-select: none;"><!-- Cabecera con selector integrado -->
<div style="background-color: #fffbeb !important; border: 1px solid #fed7aa !important; border-left: 6px solid #ea580c !important; border-radius: 8px !important; padding: 14px 18px !important; display: flex !important; justify-content: space-between !important; align-items: center !important; flex-wrap: wrap !important; gap: 12px !important; margin-bottom: 16px !important;">
<div><span style="font-size: 0.82rem; font-weight: 800; color: #ea580c; text-transform: uppercase; letter-spacing: 0.5px; display: block; margin-bottom: 3px;"> Tutor interactivo de resolución paso a paso </span>
<h3 id="tut-tit-ejemplo" style="margin: 0; color: #7c2d12; font-size: 1.25rem; font-weight: 900;">1. Identidad notable en el denominador (x² − 9)</h3>
</div>
<div style="display: flex; align-items: center; gap: 8px;"><label for="sel-ejemplo-rac" style="font-weight: 800; font-size: 0.92rem; color: #9a3412;">Ecuación:</label><select id="sel-ejemplo-rac" onchange="cargarEjemploTutor()" style="padding: 6px 12px; font-size: 0.95rem; font-weight: bold; border: 2px solid #ea580c; border-radius: 6px; background-color: #ffffff; color: #7c2d12; outline: none; cursor: pointer;">
<option value="0" selected="selected">1. Identidad notable (x² − 9)</option>
<option value="1">2. Cambio de signo en (2 − x)</option>
<option value="2">3. Factor común en x² − 3x</option>
<option value="3">4. Trinomio factorizable x² + x − 2</option>
</select></div>
</div>
<!-- Zona de la ecuación principal a resolver -->
<div style="background-color: #ffffff !important; border: 1px solid #fed7aa !important; border-radius: 8px !important; padding: 18px 20px !important; text-align: center !important; margin-bottom: 16px !important; box-shadow: 0 1px 4px rgba(0,0,0,0.04) !important;">
<div style="font-size: 0.85rem; font-weight: 800; color: #7c2d12; margin-bottom: 8px; text-transform: uppercase; letter-spacing: 0.5px;">Ecuación racional a resolver:</div>
<div id="disp-ecuacion-principal" style="font-size: 1.35rem; color: #0f172a; margin: 8px 0; overflow-x: auto;"><!-- LaTeX / MathJax --></div>
</div>
<!-- Contenedor vertical de los pasos guiados -->
<div id="caja-pasos-tutor" style="display: flex; flex-direction: column; gap: 14px; margin-bottom: 16px;"><!-- Pasos agregados progresivamente con tarjetas completas --></div>
<!-- Barra de controles inferior -->
<div style="background-color: #fffbeb !important; border: 1px solid #fed7aa !important; padding: 12px 18px !important; border-radius: 8px !important; display: flex !important; justify-content: space-between !important; align-items: center !important; flex-wrap: wrap !important; gap: 10px !important;">
<div style="font-size: 0.95rem; font-weight: 800; color: #ea580c;">Paso <span id="num-paso-actual">0</span> de <span id="total-pasos-ej">5</span></div>
<!-- BOTONES ESTILIZADOS DIRECTAMENTE INLINE -->
<div style="display: flex; gap: 10px; flex-wrap: wrap; align-items: center;">
<div role="button" onclick="reiniciarTutor()" style="background-color: #ffffff !important; border: 1px solid #cbd5e1 !important; color: #475569 !important; font-weight: 700 !important; font-size: 0.88rem !important; padding: 8px 14px !important; border-radius: 6px !important; cursor: pointer !important; text-align: center !important; line-height: 1 !important;" tabindex="0">Reiniciar</div>
<div role="button" onclick="mostrarTodosLosPasos()" style="background-color: #ffffff !important; border: 2px solid #fdba74 !important; color: #c2410c !important; font-weight: 800 !important; font-size: 0.88rem !important; padding: 7px 14px !important; border-radius: 6px !important; cursor: pointer !important; text-align: center !important; line-height: 1 !important;" tabindex="0">Ver todos los pasos</div>
<div id="btn-siguiente-paso" role="button" onclick="avanzarPasoTutor()" style="background-color: #f57c00 !important; border: 2px solid #ea580c !important; color: #ffffff !important; font-weight: 800 !important; font-size: 0.9rem !important; padding: 8px 18px !important; border-radius: 6px !important; cursor: pointer !important; box-shadow: 0 2px 6px rgba(245, 124, 0, 0.35) !important; text-transform: uppercase !important; text-align: center !important; line-height: 1 !important;" tabindex="0">Siguiente paso →</div>
</div>
</div>
</div>
<p>
<script>
(function() {
  function svgRaiz(numStr, w, tX) {
    let ancho = w || 42;
    let finX = ancho - 2;
    let posX = tX || 15;
    return `
      <span style="display: inline-flex; align-items: center; vertical-align: middle; line-height: 1;">
        <svg width="${ancho}" height="28" viewBox="0 0 ${ancho} 28" style="overflow: visible;">
          <path d="M 2 15 L 5 23 L 11 4 L ${finX} 4" 
                fill="none" 
                stroke="#c2410c" 
                stroke-width="2.2" 
                stroke-linecap="round" 
                stroke-linejoin="round" />
          <text x="${posX}" y="20" 
                fill="#c2410c" 
                font-family="-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" 
                font-size="16" 
                font-weight="800">${numStr}</text>
        </svg>
      </span>
    `;
  }

  const EJEMPLOS = [
    // EJEMPLO 1
    {
      titulo: "1. Identidad notable en el denominador (x² − 9)",
      ecuacionLaTeX: "\\[\\frac{x}{x - 3} + \\frac{x - 2}{x + 3} = \\frac{x^2 + 9}{x^2 - 9}\\]",
      pasos: [
        {
          titulo: "Paso 1: Factorizar los denominadores y calcular el m.c.m.",
          desc: "Identificamos que el denominador del segundo miembro es una diferencia de cuadrados: \\(x^2 - 9 = (x - 3)(x + 3)\\).",
          formula: "\\[\\text{m.c.m.} = (x - 3)(x + 3)\\]"
        },
        {
          titulo: "Paso 2: Valores prohibidos (restricciones de la incógnita)",
          desc: "Un denominador nunca puede valer cero. Buscamos qué valores anularían las fracciones:",
          formula: "\\[x - 3 = 0 \\implies x \\neq 3 \\qquad \\text{y} \\qquad x + 3 = 0 \\implies x \\neq -3\\]"
        },
        {
          titulo: "Paso 3: Reducir a común denominador y eliminar denominadores",
          desc: "Multiplicamos cada numerador por los factores que le faltan respecto al m.c.m.:",
          formula: "\\[x(x + 3) + (x - 2)(x - 3) = x^2 + 9\\]"
        },
        {
          titulo: "Paso 4: Desarrollar, agrupar y resolver la ecuación resultante",
          desc: "Expandimos los paréntesis y pasamos todos los términos a un miembro para obtener la forma canónica de segundo grado:",
          formula: "\\[(x^2 + 3x) + (x^2 - 5x + 6) = x^2 + 9 \\implies 2x^2 - 2x + 6 = x^2 + 9 \\implies x^2 - 2x - 3 = 0\\]"
        },
        {
          titulo: "Paso 5: Soluciones algebraicas y comprobación de validez",
          desc: "Aplicamos la fórmula general de segundo grado:<br>\\[x = \\frac{2 \\pm \\sqrt{4 - 4(1)(-3)}}{2} = \\frac{2 \\pm \\sqrt{16}}{2} = \\frac{2 \\pm 4}{2} \\implies x_1 = 3, \\quad x_2 = -1\\]",
          alerta: "⚠️ <strong>¡Comprobación obligatoria!</strong> En el Paso 2 restringimos \\(x \\neq 3\\) para no anular los denominadores. Por tanto, <strong>\\(x = 3\\) es una solución ficticia y se descarta</strong>.",
          exito: "Solución única válida: <strong>x = −1</strong>"
        }
      ]
    },

    // EJEMPLO 2
    {
      titulo: "2. Cambio de signo disimulado en el denominador",
      ecuacionLaTeX: "\\[\\frac{x + 1}{x - 2} - \\frac{4}{x^2 - 4} = \\frac{x - 1}{2 - x}\\]",
      pasos: [
        {
          titulo: "Paso 1: Detectar y corregir el orden de (2 − x)",
          desc: "Observa que \\(2 - x = -(x - 2)\\). Cambiando el signo delante de la fracción convertimos la expresión en su opuesta y unificamos los denominadores:",
          formula: "\\[\\frac{x + 1}{x - 2} - \\frac{4}{(x - 2)(x + 2)} = -\\frac{x - 1}{x - 2} \\implies \\frac{x + 1}{x - 2} + \\frac{x - 1}{x - 2} = \\frac{4}{(x - 2)(x + 2)}\\]"
        },
        {
          titulo: "Paso 2: Calcular el m.c.m. y fijar restricciones",
          desc: "Factorizamos la diferencia de cuadrados \\(x^2 - 4 = (x - 2)(x + 2)\\). El m.c.m. es \\((x - 2)(x + 2)\\):",
          formula: "\\[x \\neq 2 \\qquad \\text{y} \\qquad x \\neq -2\\]"
        },
        {
          titulo: "Paso 3: Eliminar denominadores multiplicando por el m.c.m.",
          desc: "Multiplicamos cada término de la ecuación por el m.c.m.:",
          formula: "\\[(x + 1)(x + 2) - 4 = -(x - 1)(x + 2)\\]"
        },
        {
          titulo: "Paso 4: Desarrollar paréntesis y simplificar",
          desc: "Operamos con cuidado con los signos negativos:",
          formula: "\\[(x^2 + 3x + 2) - 4 = -(x^2 + x - 2) \\implies x^2 + 3x - 2 = -x^2 - x + 2 \\implies 2x^2 + 4x - 4 = 0 \\implies x^2 + 2x - 2 = 0\\]"
        },
        {
          titulo: "Paso 5: Soluciones radicales y verificación",
          desc: "Resolvemos la ecuación de segundo grado:<br>\\[x = \\frac{-2 \\pm \\sqrt{4 - 4(1)(-2)}}{2} = \\frac{-2 \\pm \\sqrt{12}}{2} = \\frac{-2 \\pm 2\\sqrt{3}}{2} = -1 \\pm \\sqrt{3}\\]",
          exito: `Ambas soluciones son números irracionales distintos de 2 y −2. Por tanto, ambas son válidas:<br>
                 <strong>x₁ = −1 + ${svgRaiz('3', 34, 13)}</strong> &emsp; y &emsp; <strong>x₂ = −1 − ${svgRaiz('3', 34, 13)}</strong>`
        }
      ]
    },

    // EJEMPLO 3
    {
      titulo: "3. Extracción de factor común monomio en x² − 3x",
      ecuacionLaTeX: "\\[\\frac{2}{x} + \\frac{3}{x^2 - 3x} = \\frac{1}{x - 3}\\]",
      pasos: [
        {
          titulo: "Paso 1: Factorizar sacando factor común x",
          desc: "El denominador central se factoriza como monomio por binomio: \\(x^2 - 3x = x(x - 3)\\).",
          formula: "\\[\\text{m.c.m.}\\big(x,\\; x(x - 3),\\; x - 3\\big) = x(x - 3)\\]"
        },
        {
          titulo: "Paso 2: Restricciones de los denominadores",
          desc: "Identificamos los valores que harían cero los denominadores:",
          formula: "\\[x \\neq 0 \\qquad \\text{y} \\qquad x \\neq 3\\]"
        },
        {
          titulo: "Paso 3: Reducir y suprimir denominadores",
          desc: "Multiplicamos cada numerador por lo que le falta:",
          formula: "\\[2(x - 3) + 3 = 1 \\cdot x\\]"
        },
        {
          titulo: "Paso 4: Resolver la ecuación lineal",
          desc: "Obtenemos una ecuación de primer grado muy directa:",
          formula: "\\[2x - 6 + 3 = x \\implies 2x - 3 = x \\implies 2x - x = 3 \\implies x = 3\\]"
        },
        {
          titulo: "Paso 5: Comprobación crítica",
          desc: "El álgebra nos da como candidato \\(x = 3\\).",
          alerta: "⛔ <strong>¡Solución no admisible!</strong> Al inicio fijamos que \\(x \\neq 3\\), ya que anularía dos de las fracciones: \\( 3^2 - 3 \\cdot 3 = 0\\) y \\(3 - 3 = 0\\).",
          exito: "<span style='color:#dc2626;'>La ecuación <strong>NO TIENE SOLUCIÓN</strong> en los números reales.</span>"
        }
      ]
    },

    // EJEMPLO 4
    {
      titulo: "4. Trinomio de segundo grado factorizable x² + x − 2",
      ecuacionLaTeX: "\\[\\frac{x + 2}{x - 1} - \\frac{x - 6}{x^2 + x - 2} = 1\\]",
      pasos: [
        {
          titulo: "Paso 1: Factorizar el trinomio x² + x − 2",
          desc: "Buscamos dos números que multiplicados den −2 y sumados den +1: son +2 y −1.<br>Por consiguiente: \\(x^2 + x - 2 = (x - 1)(x + 2)\\).",
          formula: "\\[\\text{m.c.m.} = (x - 1)(x + 2)\\]"
        },
        {
          titulo: "Paso 2: Fijar valores prohibidos",
          desc: "Evitamos valores que anulen el m.c.m.:",
          formula: "\\[x \\neq 1 \\qquad \\text{y} \\qquad x \\neq -2\\]"
        },
        {
          titulo: "Paso 3: Multiplicar toda la ecuación por el m.c.m.",
          desc: "Atención al término independiente 1 del segundo miembro: también debe multiplicarse por el m.c.m.:",
          formula: "\\[(x + 2)(x + 2) - (x - 6) = 1 \\cdot (x - 1)(x + 2)\\]"
        },
        {
          titulo: "Paso 4: Desarrollar paréntesis cuidando el signo menos",
          desc: "El signo menos delante de la fracción afecta a todo el binomio \\((x - 6)\\):",
          formula: "\\[(x^2 + 4x + 4) - x + 6 = x^2 + x - 2 \\implies x^2 + 3x + 10 = x^2 + x - 2\\]"
        },
        {
          titulo: "Paso 5: Despejar la incógnita y verificar",
          desc: "Los términos cuadráticos \\(x^2\\) se cancelan a ambos lados, quedando una ecuación lineal simple:<br>\\[3x + 10 = x - 2 \\implies 2x = -12 \\implies x = -6\\]",
          exito: "Como \\(-6 \\neq 1\\) y \\(-6 \\neq -2\\), la solución es perfectamente válida:<br><strong>x = −6</strong>"
        }
      ]
    }
  ];

  let ejemploIdx = 0;
  let pasoActual = 0;

  function repintarMathJax() {
    if (window.MathJax && window.MathJax.typesetPromise) {
      window.MathJax.typesetPromise();
    } else if (window.MathJax && window.MathJax.Hub) {
      window.MathJax.Hub.Queue(["Typeset", window.MathJax.Hub]);
    }
  }

  window.cargarEjemploTutor = function() {
    ejemploIdx = parseInt(document.getElementById('sel-ejemplo-rac').value);
    pasoActual = 0;

    const ej = EJEMPLOS[ejemploIdx];
    document.getElementById('tut-tit-ejemplo').textContent = ej.titulo;
    document.getElementById('disp-ecuacion-principal').innerHTML = ej.ecuacionLaTeX;
    document.getElementById('total-pasos-ej').textContent = ej.pasos.length;
    document.getElementById('num-paso-actual').textContent = '0';

    const cont = document.getElementById('caja-pasos-tutor');
    cont.innerHTML = `
      <div style="text-align: center !important; padding: 25px 15px !important; color: #7c2d12 !important; font-weight: 600 !important; background-color: #ffffff !important; border-radius: 8px !important; border: 1px dashed #fed7aa !important;">
        Pulsa el botón <strong>«Siguiente paso»</strong> para comenzar el análisis guiado de esta ecuación.
      </div>
    `;

    document.getElementById('btn-siguiente-paso').style.display = 'inline-flex';
    repintarMathJax();
  };

  window.avanzarPasoTutor = function() {
    const ej = EJEMPLOS[ejemploIdx];
    const cont = document.getElementById('caja-pasos-tutor');

    if (pasoActual === 0) {
      cont.innerHTML = '';
    }

    if (pasoActual < ej.pasos.length) {
      const p = ej.pasos[pasoActual];
      let div = document.createElement('div');

      // Aplicación de estilos inline obligatorios para aislar de eXeLearning
      div.style.cssText = "background-color: #ffffff !important; border: 1px solid #fed7aa !important; border-left: 5px solid #ea580c !important; border-radius: 8px !important; padding: 16px 18px !important; box-shadow: 0 2px 6px rgba(234, 88, 12, 0.06) !important;";

      let contenido = `
        <div style="font-size: 1rem !important; font-weight: 800 !important; color: #9a3412 !important; margin-bottom: 8px !important; display: flex !important; align-items: center !important; gap: 6px !important;">
          <span style="color: #ea580c !important;">■</span> ${p.titulo}
        </div>
        <div style="font-size: 0.94rem !important; color: #334155 !important; line-height: 1.55 !important; margin-bottom: 10px !important;">
          ${p.desc}
        </div>
      `;

      if (p.formula) {
        contenido += `
          <div style="background-color: #fff7ed !important; border: 1px solid #ffedd5 !important; border-radius: 6px !important; padding: 10px 14px !important; text-align: center !important; font-size: 1.15rem !important; color: #0f172a !important; overflow-x: auto !important; margin-bottom: 6px !important;">
            ${p.formula}
          </div>
        `;
      }
      if (p.alerta) {
        contenido += `
          <div style="background-color: #fef2f2 !important; border: 1px solid #fecaca !important; border-left: 5px solid #dc2626 !important; border-radius: 8px !important; padding: 12px 16px !important; font-size: 0.93rem !important; color: #991b1b !important; line-height: 1.5 !important; margin-top: 10px !important;">
            ${p.alerta}
          </div>
        `;
      }
      if (p.exito) {
        contenido += `
          <div style="background-color: #fffbeb !important; border: 2px solid #f59e0b !important; border-radius: 8px !important; padding: 12px 16px !important; font-size: 1.05rem !important; font-weight: 800 !important; color: #9a3412 !important; text-align: center !important; line-height: 1.4 !important; margin-top: 10px !important;">
            ${p.exito}
          </div>
        `;
      }

      div.innerHTML = contenido;
      cont.appendChild(div);

      pasoActual++;
      document.getElementById('num-paso-actual').textContent = pasoActual;

      if (pasoActual === ej.pasos.length) {
        document.getElementById('btn-siguiente-paso').style.display = 'none';
      }

      repintarMathJax();
    }
  };

  window.mostrarTodosLosPasos = function() {
    const ej = EJEMPLOS[ejemploIdx];
    while (pasoActual < ej.pasos.length) {
      avanzarPasoTutor();
    }
  };

  window.reiniciarTutor = function() {
    cargarEjemploTutor();
  };

  cargarEjemploTutor();
})();
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}
